package net.civeira.phylax.features.document.templatesnippet.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.templatesnippet.domain.TemplateSnippet;
import net.civeira.phylax.features.document.templatesnippet.domain.gateway.TemplateSnippetCursor;
import net.civeira.phylax.features.document.templatesnippet.domain.gateway.TemplateSnippetFilter;

class TemplateSnippetSlider extends Slider<TemplateSnippet> {

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateSnippetCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateSnippetFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<TemplateSnippetFilter, TemplateSnippetCursor, Iterator<TemplateSnippet>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  TemplateSnippetSlider(final Iterator<TemplateSnippet> multi, final int limit,
      final BiFunction<TemplateSnippetFilter, TemplateSnippetCursor, Iterator<TemplateSnippet>> gateway,
      final TemplateSnippetFilter filter, final TemplateSnippetCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param templateSnippets
   * @param limit
   * @return
   */
  @Override
  public Iterator<TemplateSnippet> next(List<TemplateSnippet> templateSnippets, int limit) {
    TemplateSnippet last = templateSnippets.get(templateSnippets.size() - 1);
    TemplateSnippetCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
